'use strict';

// @test/math uses shared-utils as a transitive dependency
const utils = require('shared-utils');

exports.add = function(a, b) {
  return utils.validate(a, b) ? a + b : NaN;
};

exports.multiply = function(a, b) {
  return utils.validate(a, b) ? a * b : NaN;
};

exports.version = '2.0.0';
exports.utilsVersion = utils.version;
